def process_scores(scores):
    """Calculate the average of valid integer scores between 0 and 100."""
    assert isinstance(scores, list), 'scores must be a list'
    for s in scores:
        assert isinstance(s, int), f'Score {s!r} must be an integer'
        assert 0 <= s <= 100, f'Score {s!r} must be between 0 and 100'
    return sum(scores) / len(scores)

